#[cfg(test)]mod resurrection61_request_development_tests {
 use super::*;
 fn world()->World {let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.insert(61);w.mp=Some([1,200]);w.hp=Some([1,200]);let mut a=w.own_actor().unwrap().clone();a.id=0xf1234567;a.x+=1;a.dead=true;a.incarnation+=10;w.actors.insert(a.id,a);w}
 #[test]fn corpse_object_request_has_no_xy_and_does_not_predict_mp_or_revive(){let w=world();let before=serde_json::to_value(&w).unwrap();let mut body=vec![20,7,4];body.extend(0xf1234567_u32.to_le_bytes());assert_eq!(request(&w,61,Some(0xf1234567)).unwrap(),body);assert_eq!(reuse_millis(61),10);assert_eq!(serde_json::to_value(&w).unwrap(),before);assert!(request(&w,61,None).is_err());assert!(request(&w,61,Some(w.own_actor().unwrap().id)).is_err());}
 #[test]fn native_screen_and_book_gate_do_not_admit_living_or_stale_corpse(){let mut w=world();let own=w.own_actor().unwrap().clone();w.actors.get_mut(&0xf1234567).unwrap().x=own.x+19;assert!(request(&w,61,Some(0xf1234567)).is_err());w.actors.get_mut(&0xf1234567).unwrap().x=own.x+1;w.actors.get_mut(&0xf1234567).unwrap().dead=false;assert!(request(&w,61,Some(0xf1234567)).is_err());w.actors.get_mut(&0xf1234567).unwrap().dead=true;w.learned_skills.remove(&61);assert!(request(&w,61,Some(0xf1234567)).is_err());}
 #[test]fn corpse_intent_does_not_upgrade_live_selection_and_retires_on_death_action_or_new_life(){let mut w=world();let t=super::super::native_skill_selection::Target::capture(&w,0xf1234567).unwrap();assert_eq!(t.resolve_for_skill(&w,61),Some(0xf1234567));w.actors.get_mut(&0xf1234567).unwrap().action_sequence+=1;assert!(t.resolve_for_skill(&w,61).is_none());w.actors.get_mut(&0xf1234567).unwrap().dead=false;let live=super::super::native_skill_selection::Target::capture(&w,0xf1234567).unwrap();w.actors.get_mut(&0xf1234567).unwrap().dead=true;assert!(live.resolve_for_skill(&w,61).is_none());}
}
